import{I as a,c as r,d as t,O as n}from"./chunks/framework.N7KwZWfa-ghp20261122.js";const p=JSON.parse('{"title":"少女迴戰新區｜日服、繁中服開服公告與選服","titleTemplate":false,"description":"查少女迴戰新區的開服公告、伺服器名稱和開放時間，瞭解日服與繁中服選服、新手活動和重生服歷史。","frontmatter":{"title":"少女迴戰新區｜日服、繁中服開服公告與選服","titleTemplate":false,"description":"查少女迴戰新區的開服公告、伺服器名稱和開放時間，瞭解日服與繁中服選服、新手活動和重生服歷史。","breadcrumbLabel":"新區與開服","lastmod":"2026-11-16"},"headers":[],"relativePath":"servers/index.md","filePath":"servers/index.md"}'),l={name:"servers/index.md"};function s(i,e,o,h,d,c){return r(),t("div",null,[...e[0]||(e[0]=[n('<article class="page-shell knowledge-page reference-guide"><h1 id="少女迴戰新區與開服查詢" tabindex="-1">少女迴戰新區與開服查詢 <a class="header-anchor" href="#少女迴戰新區與開服查詢" aria-label="Permalink to &quot;少女迴戰新區與開服查詢&quot;">​</a></h1><p>查新區時，開啟所玩版本的登入頁，在伺服器列表核對大區、服名和是否開放。計劃和朋友一起開局時，先確認雙方選擇同一版本和伺服器。</p><h2 id="去哪裡看開服公告" tabindex="-1">去哪裡看開服公告 <a class="header-anchor" href="#去哪裡看開服公告" aria-label="Permalink to &quot;去哪裡看開服公告&quot;">​</a></h2><ul><li><strong>繁中服</strong>。在登入頁開啟「公告」，查詢「更新公告」中的「開服公告」，按顯示的服名、日期和時間選服。<a href="https://forum.gamer.com.tw/Co.php?bsn=71737&amp;sn=8923" target="_blank" rel="noreferrer">繁中服玩家記錄的查詢步驟</a></li><li><strong>日服</strong>。在《少女廻戦》登入頁檢視選服列表和遊戲內公告。也可查閱 <a href="https://x.com/shoujokaisen" target="_blank" rel="noreferrer">日服官方 X</a> 與<a href="https://discord.gg/9cW4hQKuHN" target="_blank" rel="noreferrer">日服官方 Discord</a>。</li></ul><h2 id="新區開局要查哪些資料" tabindex="-1">新區開局要查哪些資料 <a class="header-anchor" href="#新區開局要查哪些資料" aria-label="Permalink to &quot;新區開局要查哪些資料&quot;">​</a></h2><ol><li>進入選定伺服器後，開啟遊戲內活動頁，核對新手福利的適用伺服器、參與條件與結束時間。</li><li>用<a href="/zh-hant/beginner/#beginner-tasks">新手攻略</a>對照五日任務和獎勵。查<a href="/zh-hant/beginner/#beginner-boxes">階段寶箱</a>時，按實際開服日期選擇對應檔期。</li><li>推主線時可查 <a href="/zh-hant/teams/#pve">PVE 首排陣容</a>，招募前用<a href="/zh-hant/heroes/">武將圖鑑</a>核對技能與各區服登場時間。</li></ol><p>繁中服曾在 2024 年兩週年公佈重生服與 VIP 等級繼承。活動背景見<a href="/zh-hant/events/anniversary-2024/">登入送 2024 連抽檔案</a>。安裝對應客戶端見 <a href="/zh-hant/download/">iOS 與安卓下載</a>。</p></article>',1)])])}const _=a(l,[["render",s]]);export{p as __pageData,_ as default};
